public interface Measurable {
    /** Returns the area of this shape in square units. */
    double getArea();

    /** Returns the perimeter of this shape in linear units. */
    double getPerimeter();
}

public class Rectangle implements Measurable {
    private double length, width;

    public Rectangle(double length, double width) {
        this.length = length;
        this.width = width;
    }

    @Override
    public double getArea() { return length * width; }

    @Override
    public double getPerimeter() { return 2 * (length + width); }
}

public class Circle implements Measurable {
    private double radius;

    public Circle(double radius) { this.radius = radius; }

    @Override
    public double getArea() { return Math.PI * radius * radius; }

    @Override
    public double getPerimeter() { return 2 * Math.PI * radius; }
}

Measurable[] shapes = { new Rectangle(4, 6), new Circle(3) };

for (Measurable s : shapes) {
    System.out.printf("Area %.2f, perimeter %.2f%n", s.getArea(), s.getPerimeter());
}

public interface Measurable {
    double getArea();

    default String describe() {           // has a body; implementers may override it
        return "Area: " + getArea();
    }
}
